Ordnode.Valid'.node3L.code:
Ordnode.Valid'.node3L.{u_1} {α : Type u_1} [Preorder α] {l : Ordnode α} {x : α} {m : Ordnode α} {y : α} {r : Ordnode α}
  {o₁ : WithBot α} {o₂ : WithTop α} (hl : Valid' o₁ l ↑x) (hm : Valid' (↑x) m ↑y) (hr : Valid' (↑y) r o₂)
  (H1 : BalancedSz l.size m.size) (H2 : BalancedSz (l.size + m.size + 1) r.size) : Valid' o₁ (l.node3L x m y r) o₂

Ordnode.Valid'.node3R.code:
Ordnode.Valid'.node3R.{u_1} {α : Type u_1} [Preorder α] {l : Ordnode α} {x : α} {m : Ordnode α} {y : α} {r : Ordnode α}
  {o₁ : WithBot α} {o₂ : WithTop α} (hl : Valid' o₁ l ↑x) (hm : Valid' (↑x) m ↑y) (hr : Valid' (↑y) r o₂)
  (H1 : BalancedSz l.size (m.size + r.size + 1)) (H2 : BalancedSz m.size r.size) : Valid' o₁ (l.node3R x m y r) o₂

Ordnode.Valid'.rotateL.code:
Ordnode.Valid'.rotateL.{u_1} {α : Type u_1} [Preorder α] {l : Ordnode α} {x : α} {r : Ordnode α} {o₁ : WithBot α}
  {o₂ : WithTop α} (hl : Valid' o₁ l ↑x) (hr : Valid' (↑x) r o₂) (H1 : ¬l.size + r.size ≤ 1)
  (H2 : delta * l.size < r.size) (H3 : 2 * r.size ≤ 9 * l.size + 5 ∨ r.size ≤ 3) : Valid' o₁ (l.rotateL x r) o₂

Ordnode.Valid'.rotateR.code:
Ordnode.Valid'.rotateR.{u_1} {α : Type u_1} [Preorder α] {l : Ordnode α} {x : α} {r : Ordnode α} {o₁ : WithBot α}
  {o₂ : WithTop α} (hl : Valid' o₁ l ↑x) (hr : Valid' (↑x) r o₂) (H1 : ¬l.size + r.size ≤ 1)
  (H2 : delta * r.size < l.size) (H3 : 2 * l.size ≤ 9 * r.size + 5 ∨ l.size ≤ 3) : Valid' o₁ (l.rotateR x r) o₂

Ordnode.Valid'.balance'_aux.code:
Ordnode.Valid'.balance'_aux.{u_1} {α : Type u_1} [Preorder α] {l : Ordnode α} {x : α} {r : Ordnode α} {o₁ : WithBot α}
  {o₂ : WithTop α} (hl : Valid' o₁ l ↑x) (hr : Valid' (↑x) r o₂) (H₁ : 2 * r.size ≤ 9 * l.size + 5 ∨ r.size ≤ 3)
  (H₂ : 2 * l.size ≤ 9 * r.size + 5 ∨ l.size ≤ 3) : Valid' o₁ (l.balance' x r) o₂

Ordnode.Valid'.balance'_lemma.code:
Ordnode.Valid'.balance'_lemma.{u_2} {α : Type u_2} {l : Ordnode α} {l' : ℕ} {r : Ordnode α} {r' : ℕ}
  (H1 : BalancedSz l' r') (H2 : l.size.dist l' ≤ 1 ∧ r.size = r' ∨ r.size.dist r' ≤ 1 ∧ l.size = l') :
  2 * r.size ≤ 9 * l.size + 5 ∨ r.size ≤ 3

Ordnode.Valid'.eraseMax_aux.code:
Ordnode.Valid'.eraseMax_aux.{u_1} {α : Type u_1} [Preorder α] {s : ℕ} {l : Ordnode α} {x : α} {r : Ordnode α}
  {o₁ : WithBot α} {o₂ : WithTop α} (H : Valid' o₁ (node s l x r) o₂) :
  Valid' o₁ (l.node' x r).eraseMax ↑(findMax' x r) ∧ (l.node' x r).size = (l.node' x r).eraseMax.size + 1

Ordnode.Valid'.eraseMin_aux.code:
Ordnode.Valid'.eraseMin_aux.{u_1} {α : Type u_1} [Preorder α] {s : ℕ} {l : Ordnode α} {x : α} {r : Ordnode α}
  {o₁ : WithBot α} {o₂ : WithTop α} (H : Valid' o₁ (node s l x r) o₂) :
  Valid' (↑(l.findMin' x)) (l.node' x r).eraseMin o₂ ∧ (l.node' x r).size = (l.node' x r).eraseMin.size + 1

Ordnode.Valid'.glue_aux.code:
Ordnode.Valid'.glue_aux.{u_1} {α : Type u_1} [Preorder α] {l r : Ordnode α} {o₁ : WithBot α} {o₂ : WithTop α}
  (hl : Valid' o₁ l o₂) (hr : Valid' o₁ r o₂) (sep : All (fun x => All (fun y => x < y) r) l)
  (bal : BalancedSz l.size r.size) : Valid' o₁ (l.glue r) o₂ ∧ (l.glue r).size = l.size + r.size

Ordnode.Valid'.glue.code:
Ordnode.Valid'.glue.{u_1} {α : Type u_1} [Preorder α] {l : Ordnode α} {x : α} {r : Ordnode α} {o₁ : WithBot α}
