Fin.consCases.eq_1.code:
Fin.consCases.eq_1.{u, v} {n : ℕ} {α : Fin (n + 1) → Type u} {P : ((i : Fin n.succ) → α i) → Sort v}
  (h : (x₀ : α 0) → (x : (i : Fin n) → α i.succ) → P (cons x₀ x)) (x : (i : Fin n.succ) → α i) :
  consCases h x = _root_.cast ⋯ (h (x 0) (tail x))

Fin.consCases_cons.code:
Fin.consCases_cons.{u, v} {n : ℕ} {α : Fin (n + 1) → Type u} {P : ((i : Fin n.succ) → α i) → Sort v}
  (h : (x₀ : α 0) → (x : (i : Fin n) → α i.succ) → P (cons x₀ x)) (x₀ : α 0) (x : (i : Fin n) → α i.succ) :
  consCases h (cons x₀ x) = h x₀ x

Fin.snocCases.eq_1.code:
Fin.snocCases.eq_1.{u, u_1} {n : ℕ} {α : Fin (n + 1) → Type u} {P : ((i : Fin n.succ) → α i) → Sort u_1}
  (h : (xs : (i : Fin n) → α i.castSucc) → (x : α (last n)) → P (snoc xs x)) (x : (i : Fin n.succ) → α i) :
  snocCases h x = _root_.cast ⋯ (h (init x) (x (last n)))

Fin.insertNth_eq_iff.code:
Fin.insertNth_eq_iff.{u} {n : ℕ} {α : Fin (n + 1) → Type u} {p : Fin (n + 1)} {a : α p}
  {f : (i : Fin n) → α (p.succAbove i)} {g : (j : Fin (n + 1)) → α j} :
  p.insertNth a f = g ↔ a = g p ∧ f = p.removeNth g

Fin.eq_insertNth_iff.code:
Fin.eq_insertNth_iff.{u} {n : ℕ} {α : Fin (n + 1) → Type u} {p : Fin (n + 1)} {a : α p}
  {f : (i : Fin n) → α (p.succAbove i)} {g : (j : Fin (n + 1)) → α j} :
  g = p.insertNth a f ↔ g p = a ∧ p.removeNth g = f

Fin.insertNth_le_iff.code:
Fin.insertNth_le_iff.{u} {n : ℕ} {α : Fin (n + 1) → Type u} [(i : Fin (n + 1)) → Preorder (α i)] {i : Fin (n + 1)}
  {x : α i} {p : (j : Fin n) → α (i.succAbove j)} {q : (j : Fin (n + 1)) → α j} :
  i.insertNth x p ≤ q ↔ x ≤ q i ∧ p ≤ fun j => q (i.succAbove j)

Fin.le_insertNth_iff.code:
Fin.le_insertNth_iff.{u} {n : ℕ} {α : Fin (n + 1) → Type u} [(i : Fin (n + 1)) → Preorder (α i)] {i : Fin (n + 1)}
  {x : α i} {p : (j : Fin n) → α (i.succAbove j)} {q : (j : Fin (n + 1)) → α j} :
  q ≤ i.insertNth x p ↔ q i ≤ x ∧ (fun j => q (i.succAbove j)) ≤ p

Tuple.bubble_sort_induction.code:
Tuple.bubble_sort_induction.{u_1} {n : ℕ} {α : Type u_1} [LinearOrder α] {f : Fin n → α} {P : (Fin n → α) → Prop}
  (hf : P f) (h : ∀ (g : Fin n → α) (i j : Fin n), i < j → g j < g i → P g → P (g ∘ ⇑(Equiv.swap i j))) :
