IsMaxChain.range_fin_of_covBy.code:
IsMaxChain.range_fin_of_covBy.{u_1} {α : Type u_1} [PartialOrder α] [BoundedOrder α] {n : ℕ} {f : Fin (n + 1) → α}
  (h0 : f 0 = ⊥) (hlast : f (Fin.last n) = ⊤) (hcovBy : ∀ (k : Fin n), f k.castSucc ⩿ f k.succ) :
  IsMaxChain (fun x x_1 => x ≤ x_1) (range f)

IsMaxChain.range_fin_of_covBy.comment:
Let `f : Fin (n + 1) → α` be an `(n + 1)`-tuple `(f₀, …, fₙ)` such that
- `f₀ = ⊥` and `fₙ = ⊤`;
- `fₖ₊₁` weakly covers `fₖ` for all `0 ≤ k < n`;
  this means that `fₖ ≤ fₖ₊₁` and there is no `c` such that `fₖ<c<fₖ₊₁`.
Then the range of `f` is a maximal chain.

Flag.rangeFin.comment:
Let `f : Fin (n + 1) → α` be an `(n + 1)`-tuple `(f₀, …, fₙ)` such that
- `f₀ = ⊥` and `fₙ = ⊤`;
- `fₖ₊₁` weakly covers `fₖ` for all `0 ≤ k < n`;
  this means that `fₖ ≤ fₖ₊₁` and there is no `c` such that `fₖ<c<fₖ₊₁`.
Then the range of `f` is a `Flag α`.

Multiset.recOn_0.code:
Multiset.recOn_0.{u_1, u_3} {α : Type u_1} {C : Multiset α → Sort u_3} {C_0 : C 0}
  {C_cons : (a : α) → (m : Multiset α) → C m → C (a ::ₘ m)}
  {C_cons_heq :
    ∀ (a a' : α) (m : Multiset α) (b : C m),
      HEq (C_cons a (a' ::ₘ m) (C_cons a' m b)) (C_cons a' (a ::ₘ m) (C_cons a m b))} :
  Multiset.recOn 0 C_0 C_cons C_cons_heq = C_0

Multiset.recOn_cons.code:
Multiset.recOn_cons.{u_1, u_3} {α : Type u_1} {C : Multiset α → Sort u_3} {C_0 : C 0}
  {C_cons : (a : α) → (m : Multiset α) → C m → C (a ::ₘ m)}
  {C_cons_heq :
    ∀ (a a' : α) (m : Multiset α) (b : C m),
      HEq (C_cons a (a' ::ₘ m) (C_cons a' m b)) (C_cons a' (a ::ₘ m) (C_cons a m b))}
  (a : α) (m : Multiset α) : (a ::ₘ m).recOn C_0 C_cons C_cons_heq = C_cons a m (m.recOn C_0 C_cons C_cons_heq)

Multiset.strongDownwardInduction.code:
Multiset.strongDownwardInduction.{u_1, u_3} {α : Type u_1} {p : Multiset α → Sort u_3} {n : ℕ}
  (H : (t₁ : Multiset α) → ({t₂ : Multiset α} → card t₂ ≤ n → t₁ < t₂ → p t₂) → card t₁ ≤ n → p t₁) (s : Multiset α) :
  card s ≤ n → p s

Multiset.strongDownwardInduction.eq_1.code:
Multiset.strongDownwardInduction.eq_1.{u_1, u_3} {α : Type u_1} {p : Multiset α → Sort u_3} {n : ℕ}
  (H : (t₁ : Multiset α) → ({t₂ : Multiset α} → card t₂ ≤ n → t₁ < t₂ → p t₂) → card t₁ ≤ n → p t₁) (s : Multiset α) :
  strongDownwardInduction H s = H s fun {t} ht _h => strongDownwardInduction H t ht

Multiset.strongDownwardInduction_eq.code:
Multiset.strongDownwardInduction_eq.{u_1, u_3} {α : Type u_1} {p : Multiset α → Sort u_3} {n : ℕ}
  (H : (t₁ : Multiset α) → ({t₂ : Multiset α} → card t₂ ≤ n → t₁ < t₂ → p t₂) → card t₁ ≤ n → p t₁) (s : Multiset α) :
  strongDownwardInduction H s = H s fun {t₂} ht _hst => strongDownwardInduction H t₂ ht

Multiset.strongDownwardInductionOn_eq.code:
Multiset.strongDownwardInductionOn_eq.{u_1, u_3} {α : Type u_1} {p : Multiset α → Sort u_3} (s : Multiset α) {n : ℕ}
  (H : (t₁ : Multiset α) → ({t₂ : Multiset α} → card t₂ ≤ n → t₁ < t₂ → p t₂) → card t₁ ≤ n → p t₁) :
  (fun a => s.strongDownwardInductionOn H a) = H s fun {t} ht _h => t.strongDownwardInductionOn H ht

Multiset.pmap_congr.code:
Multiset.pmap_congr.{v, u_1} {α : Type u_1} {β : Type v} {p q : α → Prop} {f : (a : α) → p a → β}
  {g : (a : α) → q a → β} (s : Multiset α) {H₁ : ∀ a ∈ s, p a} {H₂ : ∀ a ∈ s, q a} :
