  (hst : Rel r s t) : Rel p (s.bind f) (t.bind g)

Multiset.Pi.cons_swap.code:
Multiset.Pi.cons_swap.{v, u_1} {α : Type u_1} [DecidableEq α] {δ : α → Sort v} {a a' : α} {b : δ a} {b' : δ a'}
