  sigmaLift f a b = if h : a.fst = b.fst then map (Embedding.sigmaMk b.fst) (f (h ▸ a.snd) b.snd) else ∅

Finset.mem_sigmaLift.code:
Finset.mem_sigmaLift.{u_1, u_2, u_3, u_4} {ι : Type u_1} {α : ι → Type u_2} {β : ι → Type u_3} {γ : ι → Type u_4}
